class TestRouteCaptureScoping(unittest.TestCase):
    @classmethod
    def setUpClass(cls) -> None:
        cls.index = build_repo_index(REPO_ROOT)

    def named_routes(self, goal: str) -> list[str]:
        return [route for route, _module in _routes_named_in_goal(goal, self.index)]

    def test_exam_88b_goal_yields_no_capture(self) -> None:
        self.assertEqual(self.named_routes(GOAL_88B), [])
        self.assertEqual(_route_goal_shape(GOAL_88B, REPO_ROOT, delta=False), "")

    def test_exam_88c_goal_yields_no_capture(self) -> None:
        self.assertEqual(self.named_routes(GOAL_88C), [])
        self.assertEqual(_route_goal_shape(GOAL_88C, REPO_ROOT, delta=False), "")

    def test_genuine_route_goal_still_captures(self) -> None:
        self.assertEqual(self.named_routes(GOAL_HEALTH), ["/health"])
        shape = _route_goal_shape(GOAL_HEALTH, REPO_ROOT, delta=False)
        self.assertIn("ROUTE GOAL", shape)

    def test_spec_prose_slash_token_is_not_a_route_subject(self) -> None:
        goal = "The server logs method/path/status only - never headers, never bodies."
        self.assertEqual(self.named_routes(goal), [])

    def test_contract_listing_is_not_a_route_subject(self) -> None:
        goal = "- POST /pairing/register (node): 201 new, 200 idempotent -> public view."
        self.assertEqual(self.named_routes(goal), [])

    def test_file_path_mention_is_not_a_route_subject(self) -> None:
        goal = "Edit freetalon/pairing/server.py to change what it logs."
        self.assertEqual(self.named_routes(goal), [])

    def test_intent_framed_route_goal_captures(self) -> None:
        goal = "Fix the /status endpoint so it also reports the critic state."
        self.assertEqual(self.named_routes(goal), ["/status"])


if __name__ == "__main__":
    unittest.main()
